class Solution {
public:
    int maxWidthRamp(vector<int>& nums) {
        vector<int> st;
        for (int i = 0; i < (int)nums.size(); i++) {
            if (st.empty() || nums[st.back()] > nums[i]) {
                st.push_back(i);
            }
        }
        int max_width = 0;
        for (int j = (int)nums.size() - 1; j >= 0; j--) {
            while (!st.empty() && nums[j] >= nums[st.back()]) {
                max_width = max(max_width, j - st.back());
                st.pop_back();
            }
        }
        return max_width;
    }
};

class Solution {
    public int maxWidthRamp(int[] nums) {
        int n = nums.length;
        int[] st = new int[n];
        int top = 0;
        for (int i = 0; i < n; i++) {
            if (top == 0 || nums[st[top - 1]] > nums[i]) {
                st[top++] = i;
            }
        }
        int maxWidth = 0;
        for (int j = n - 1; j >= 0; j--) {
            while (top > 0 && nums[j] >= nums[st[top - 1]]) {
                maxWidth = Math.max(maxWidth, j - st[--top]);
            }
        }
        return maxWidth;
    }
}

var maxWidthRamp = function(nums) {
    const st = [];
    for (let i = 0; i < nums.length; i++) {
        if (st.length === 0 || nums[st[st.length - 1]] > nums[i]) {
            st.push(i);
        }
    }
    let maxWidth = 0;
    for (let j = nums.length - 1; j >= 0; j--) {
        while (st.length > 0 && nums[j] >= nums[st[st.length - 1]]) {
            maxWidth = Math.max(maxWidth, j - st.pop());
        }
    }
